const WORK_EMAIL_DOMAIN = 'demo-corp.test';

const VALID_ROLES = ['ENG_JUNIOR', 'ENG_SENIOR', 'SALES_REP',
                     'FIN_ANALYST', 'SUPPORT_AGENT', 'IT_ADMIN'];
const VALID_DEPTS = ['Engineering', 'Sales', 'Finance', 'Support', 'IT'];
const ROLE_DEPT = {
  ENG_JUNIOR: 'Engineering', ENG_SENIOR: 'Engineering',
  SALES_REP: 'Sales',        FIN_ANALYST: 'Finance',
  SUPPORT_AGENT: 'Support',  IT_ADMIN: 'IT',
};

const f = $input.first().json;
const s = (v) => String(v ?? '').trim();

const req = {
  request_type:   s(f['Request Type']).toLowerCase(),
  employee_ref:   s(f['Employee Reference']).toUpperCase(),
  full_name:      s(f['Full Name']),
  personal_email: s(f['Personal Email']).toLowerCase() || null,
  department:     s(f['Department']),
  role_code:      s(f['Role Code']).toUpperCase(),
  manager_email:  s(f['Manager Email']).toLowerCase(),
  effective_date: s(f['Effective Date']).slice(0, 10),
  requested_by:   s(f['Requested By']).toLowerCase(),
  notes:          s(f['Notes']),
};

const parts = req.full_name
  .normalize('NFKD')
  .replace(/[^\w\s-]/g, '')
  .trim()
  .toLowerCase()
  .split(/\s+/)
  .filter(Boolean);
const local = parts.length >= 2 ? `${parts[0]}.${parts[parts.length - 1]}`
                                : (parts[0] || 'unknown');
req.work_email = `${local}@${WORK_EMAIL_DOMAIN}`;

const errors = [];
const emailRe = /^[^@\s]+@[^@\s]+\.[^@\s]+$/;
const dateRe = /^\d{4}-\d{2}-\d{2}$/;

if (!['onboard', 'offboard'].includes(req.request_type)) {
  errors.push('request_type must be onboard or offboard');
}
if (!/^E-\d{3,}$/.test(req.employee_ref)) {
  errors.push('employee_ref must look like E-001');
}
if (req.full_name.length < 3) {
  errors.push('full_name is too short');
}
if (!VALID_ROLES.includes(req.role_code)) {
  errors.push(`role_code must be one of ${VALID_ROLES.join(', ')}`);
}
if (!VALID_DEPTS.includes(req.department)) {
  errors.push(`department must be one of ${VALID_DEPTS.join(', ')}`);
}
if (ROLE_DEPT[req.role_code] && ROLE_DEPT[req.role_code] !== req.department) {
  errors.push(`role ${req.role_code} belongs to ${ROLE_DEPT[req.role_code]}, not ${req.department}`);
}
if (!emailRe.test(req.manager_email))  errors.push('manager_email is not a valid email');
if (!emailRe.test(req.requested_by))   errors.push('requested_by is not a valid email');
if (req.personal_email && !emailRe.test(req.personal_email)) {
  errors.push('personal_email is not a valid email');
}
if (!dateRe.test(req.effective_date))  errors.push('effective_date must be YYYY-MM-DD');

req.idempotency_root = `${req.request_type}:${req.employee_ref}:${req.effective_date}`;
req.start_date  = req.request_type === 'onboard'  ? req.effective_date : null;
req.end_date    = req.request_type === 'offboard' ? req.effective_date : null;
req.valid       = errors.length === 0;
req.errors      = errors;
req.received_at = new Date().toISOString();

return [{ json: req }];

const req = $('Normalize Request').first().json;
const employee = $('Upsert Employee').first().json;
const items = $input.all().map(i => i.json);

const steps = [];

if (req.request_type === 'onboard') {
  const ents = items
    .filter(r => r && r.action_type)
    .sort((a, b) => a.step_order - b.step_order);

  if (ents.length === 0) {
    throw new Error(
      `No entitlements defined for role ${req.role_code} in ${req.department}. ` +
      `Add rows to role_entitlements before provisioning this role.`
    );
  }
  for (const e of ents) {
    steps.push({
      step_order:    e.step_order,
      action_type:   e.action_type,
      target_system: e.target_system,
      resource:      e.resource || '',
      is_privileged: e.is_privileged === true,
    });
  }
} else {
  const res = items[0] || {};
  const status = res.statusCode;
  const user = res.body || {};

  if (status !== 200) {
    throw new Error(
      `Cannot plan offboarding: IdP returned ${status} for ${req.work_email}.`
    );
  }

  steps.push({ step_order: 10, action_type: 'revoke_sessions',
               target_system: 'mockidp', resource: '', is_privileged: false });

  let order = 20;
  for (const g of (user.groups || [])) {
    steps.push({ step_order: order++, action_type: 'remove_group',
                 target_system: 'mockidp', resource: g, is_privileged: false });
  }
  order = 50;
  for (const sku of (user.licenses || [])) {
    steps.push({ step_order: order++, action_type: 'revoke_license',
                 target_system: 'mockidp', resource: sku, is_privileged: false });
  }
  steps.push({ step_order: 90, action_type: 'suspend_account',
               target_system: 'mockidp', resource: '', is_privileged: false });
}

const hasPrivileged = steps.some(s => s.is_privileged);
const isAdminRole   = req.role_code === 'IT_ADMIN';
const requiresApproval = hasPrivileged || isAdminRole;

const rnd = () =>
  (globalThis.crypto && globalThis.crypto.randomUUID)
    ? globalThis.crypto.randomUUID().replace(/-/g, '')
    : Array.from({ length: 32 },
        () => Math.floor(Math.random() * 16).toString(16)).join('');

// The Wait node does not exist yet, so resumeUrl may be unavailable.
// Step 7 adds the Wait node and this starts returning a real URL.
let resumeUrl = null;
if (requiresApproval) {
  try { resumeUrl = $execution.resumeUrl || null; } catch (e) { resumeUrl = null; }
}

const dueHour = req.request_type === 'onboard' ? 9 : 17;
const due = DateTime
  .fromISO(req.effective_date, { zone: 'Asia/Manila' })
  .set({ hour: dueHour, minute: 0, second: 0 });

return [{ json: {
  employee_id:       employee.id,
  work_email:        req.work_email,
  run_type:          req.request_type,
  requires_approval: requiresApproval,
  approval_reason:   hasPrivileged
                       ? steps.filter(s => s.is_privileged)
                              .map(s => `${s.action_type}:${s.resource}`).join(', ')
                       : (isAdminRole ? 'role IT_ADMIN' : ''),
  approval_token:      requiresApproval ? rnd() : null,
  approval_expires_at: requiresApproval ? DateTime.now().plus({ hours: 24 }).toISO() : null,
  resume_url:          resumeUrl,
  status:              requiresApproval ? 'awaiting_approval' : 'planned',
  requested_by:        req.requested_by,
  idempotency_root:    req.idempotency_root,
  due_at:              due.toISO(),
  step_count:          steps.length,
  steps:               steps.map(s => ({
    ...s,
    idempotency_key: `${req.idempotency_root}:${s.step_order}:${s.action_type}:${s.resource}`,
  })),
} }];

const run = $('Create Run').first().json;
const plan = $('Build Plan').first().json;

return plan.steps.map(s => ({
  json: {
    run_id:          run.id,
    step_order:      s.step_order,
    action_type:     s.action_type,
    target_system:   s.target_system,
    resource:        s.resource,
    is_privileged:   s.is_privileged,
    idempotency_key: s.idempotency_key,
    status:          'pending',
  },
}));
